package org.racedaydreams.domain.strength;

import java.util.List;

/** Original equipment-specific upper-body instructions, shared by the guide template. */
final class UpperBodyTechniqueGuides {
    private UpperBodyTechniqueGuides() {}
    static TechniqueGuide forExercise(String id) {
        return switch(id) {
            case "seated-barbell-press" -> g("press","Sit against a stable upright bench, feet planted; set rack safeties and hold the bar at the front shoulders.","Press overhead without leaning away from the backrest, then lower to the shoulders under control.","Shoulders and triceps","Keep feet stable|Brace the trunk|Use a manageable load","Overarching the back|Lowering behind the neck|Straining to unrack alone","Dumbbell Shoulder Press|Machine Shoulder Press");
            case "arnold-press" -> g("press","Sit supported with a dumbbell in each hand, elbows bent in front and palms towards you.","Press overhead while rotating palms forwards, then reverse slowly through a comfortable shoulder range.","Shoulders and triceps","Keep the trunk supported|Rotate smoothly|Use light manageable weights","Forcing rotation|Leaning back to finish|Rushing the lowering","Dumbbell Shoulder Press|Overhead Press");
            case "machine-shoulder-press" -> g("press","Adjust the seat so the handles start near shoulder height; keep your back supported and feet planted.","Press the handles overhead without snapping elbows straight, then return smoothly.","Shoulders and triceps","Adjust the machine first|Keep wrists comfortable|Keep the trunk supported","Lifting away from the pad|Jerking the handles|Forcing an uncomfortable bottom position","Dumbbell Shoulder Press|Landmine Press");
            case "landmine-press" -> g("press","Secure a bar in a suitable landmine anchor; stand balanced and hold its loaded end at one shoulder.","Press the bar forwards and upwards along its arc, then return to the shoulder without twisting.","Shoulders, triceps and trunk","Check the anchor|Keep ribs controlled|Use a comfortable arc","An unsecured bar end|Leaning backwards|Twisting to lift more","Dumbbell Shoulder Press|Machine Shoulder Press");
            case "cable-lateral-raise" -> g("raise","Stand beside a low pulley, holding its handle across the front of your body with a soft elbow.","Raise the working arm out to the side towards shoulder height, then lower slowly without leaning.","Side shoulders","Use light resistance|Keep the elbow softly bent|Keep the trunk still","Shrugging to finish|Leaning away from the cable|Raising through discomfort","Lateral Raise|Machine Shoulder Press");
            case "front-raise" -> g("raise","Stand balanced with manageable dumbbells in front of the thighs and elbows softly bent.","Raise the arms forwards towards shoulder height, then lower with control without swinging.","Front shoulders","Keep ribs controlled|Stop near shoulder height|Move smoothly","Swinging with the hips|Leaning backwards|Using excessive load","Dumbbell Shoulder Press|Landmine Press");
            case "rear-delt-fly" -> g("fly","Hinge at the hips with softly bent knees, holding light dumbbells below the chest.","Open the arms out to the sides with a small elbow bend, then lower while keeping the trunk steady.","Rear shoulders and upper back","Keep the hinge steady|Use a comfortable range|Lower smoothly","Standing up to lift|Turning the fly into a row|Shrugging heavily","Reverse Pec Deck|Face Pull");
            case "reverse-pec-deck" -> g("fly","Face the machine with chest against its pad; adjust handles to a comfortable shoulder-height reach.","Open the arms outwards with soft elbows, then return without lifting your chest away.","Rear shoulders and upper back","Adjust the starting reach|Keep chest supported|Use light manageable resistance","Forcing the arms behind the body|Jerking the handles|Losing pad contact","Rear-Delt Fly|Face Pull");
            case "upright-row" -> g("row","Stand balanced holding light dumbbells in front of your thighs with comfortable wrists.","Lift elbows outwards only through a comfortable range below shoulder height, then lower smoothly.","Shoulders and upper back","Use a modest range|Keep wrists comfortable|Choose light resistance","Pulling high towards the chin|Shrugging with momentum|Continuing through shoulder discomfort","Lateral Raise|Face Pull");
            case "incline-dumbbell-curl" -> g("curl","Sit against a moderately reclined bench with feet planted and dumbbells hanging beside the body.","Curl the weights with palms upwards while keeping upper arms steady, then lower smoothly.","Elbow flexors","Keep the back supported|Keep wrists straight|Use a comfortable shoulder position","Swinging arms forwards|Forcing the shoulder stretch|Dropping the return","Dumbbell Curl|Cable Curl");
            case "preacher-curl" -> g("curl","Adjust the preacher bench so upper arms rest securely on its pad; grip a manageable EZ bar.","Curl without lifting your upper arms off the pad, then lower before elbows lock forcefully.","Elbow flexors","Keep upper arms supported|Keep wrists aligned|Lower slowly","Bouncing at the bottom|Lifting away from the pad|Using excessive load","Dumbbell Curl|Cable Curl");
            case "cable-curl" -> g("curl","Face a low pulley holding its bar underhand with elbows beside the trunk and feet stable.","Curl the bar towards the chest without moving your upper arms, then extend slowly.","Elbow flexors","Keep elbows near sides|Keep wrists aligned|Control the cable return","Rocking backwards|Lifting with the shoulders|Letting the stack slam","Barbell Curl|Dumbbell Curl");
            case "concentration-curl" -> g("curl","Sit on a stable bench and brace the working upper arm inside the thigh, holding a dumbbell palm up.","Curl towards the same shoulder, then lower slowly while keeping the upper arm supported; change sides.","Elbow flexors","Keep the upper arm steady|Use a manageable weight|Control the return","Rocking the trunk|Pressing the elbow painfully into the leg|Dropping the weight","Dumbbell Curl|Preacher Curl");
            case "spider-curl" -> g("curl","Lie chest-down on a stable inclined bench with feet supported and dumbbells hanging below the shoulders.","Curl the weights without moving the upper arms, then lower smoothly while staying on the pad.","Elbow flexors","Keep chest supported|Keep wrists comfortable|Control both directions","Lifting off the pad|Swinging elbows back|Dropping the return","Preacher Curl|Dumbbell Curl");
            case "rope-pressdown" -> g("extension","Face a high pulley and hold the rope ends with elbows bent beside the trunk.","Extend the elbows towards the thighs, separating rope ends gently; return without moving the upper arms.","Triceps","Keep elbows beside you|Keep the trunk steady|Use a controlled return","Leaning heavily over the rope|Moving through the shoulders|Slamming the weight stack","Triceps Pressdown|Dumbbell Overhead Extension");
            case "overhead-cable-extension" -> g("extension","Face away from a low pulley in a balanced stance, holding a rope behind the head with elbows pointing upwards.","Extend the elbows overhead while keeping the trunk stable, then bend them slowly to return.","Triceps","Keep ribs controlled|Use a comfortable shoulder position|Check cable clearance","Overarching the back|Moving the whole upper arm|Using excessive resistance","Dumbbell Overhead Extension|Rope Pressdown");
            case "skull-crusher" -> g("extension","Lie supported on a flat bench with feet planted, holding a light EZ bar above the chest.","Bend elbows to lower the bar just behind the forehead, then extend smoothly; keep the upper arms fairly steady.","Triceps","Start light|Keep the bar controlled|Use a spotter if needed","Dropping the bar towards the face|Flaring elbows abruptly|Turning it into a heavy bench press","Rope Pressdown|Dumbbell Overhead Extension");
            case "dumbbell-overhead-extension" -> g("extension","Sit supported and hold one manageable dumbbell securely above the head using both hands.","Bend elbows to lower the dumbbell behind the head through a comfortable range, then extend slowly.","Triceps","Check the grip before lifting|Keep ribs controlled|Plan a safe setup and exit","An insecure dumbbell grip|Overarching the back|Forcing shoulder depth","Rope Pressdown|Overhead Cable Extension");
            case "bench-dip" -> g("press","Place hands beside hips on a stable bench edge with feet flat and knees bent in front.","Move hips just clear of the edge; bend elbows through a short comfortable range, then press back up.","Triceps and front shoulders","Keep the bench stable|Use a shallow comfortable range|Keep feet supported","Dropping too deep|Moving far away from the bench|Continuing through shoulder discomfort","Push-Up|Triceps Pressdown");
            case "jm-press" -> g("extension","Use a flat bench, safeties or a spotter and a light EZ bar with a comfortable narrow grip above the upper chest.","Bend elbows to bring the bar towards the upper chest and chin region in a controlled shallow arc, then extend.","Triceps","Start very light|Keep the bar clear of the face|Use a comfortable elbow path","Dropping towards the throat|Using heavy bench-press loads|Forcing wrist or elbow discomfort","Close-Grip Bench Press|Rope Pressdown");
            default -> LowerBodyTechniqueGuides.forExercise(id);
        };
    }
    private static TechniqueGuide g(String pattern,String setup,String movement,String muscles,String cues,String mistakes,String alternatives) {
        return new TechniqueGuide(pattern,setup,movement,List.of(cues.split("\\|")),List.of(mistakes.split("\\|")),muscles,List.of(alternatives.split("\\|")));
    }
}
